import java.io.*;
import java.util.*;

public class B {
    static final long MOD = 998244353L;
    static final long INV2 = 499122177L;

    static long pow(long a, long e) {
        long res = 1L;
        while (e > 0L) {
            if ((e & 1L) == 1L) {
                res = res * a % MOD;
            }
            a = a * a % MOD;
            e >>= 1L;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        long n = in.nextInt();
        long m = in.nextInt();
        long l = in.nextInt();
        long r = in.nextInt();

        long cnt = r - l + 1L;
        long cells = n * m;

        if ((cells & 1L) == 1L) {
            out.println(pow(cnt, cells));
        } else {
            long p = pow(cnt, cells - 1L);
            long res;
            if ((cnt & 1L) == 0L) {
                res = p * (cnt / 2L) % MOD;
            } else {
                res = (p * ((cnt + 1L) / 2L) % MOD + MOD - (p + MOD - 1L) % MOD * INV2 % MOD) % MOD;
            }
            out.println(res);
        }

        out.close();
    }
}
